import{_ as t,C as r,o as e,c as h,j as i,E as n,a as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"17-dars (Mentor). ESP8266 va ESP32 mikrokontrollerlari haqida umumiy tushuncha","description":"","frontmatter":{"title":"17-dars (Mentor). ESP8266 va ESP32 mikrokontrollerlari haqida umumiy tushuncha","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"week":{"n":6,"link":"/mentor/9-sinf-iot/hafta-06/"},"g":17,"title":"ESP8266 va ESP32 mikrokontrollerlari haqida umumiy tushuncha","lead":"Kichkina va arzon chip butun uyni internetga ulashi mumkin. Bugun ESP8266 va ESP32 ning farqlarini, pinlarini va ma'lumotni bulutga yuborish yo'lini o'rganamiz.","slide":"/slaydlar/9-sinf-iot/hafta-06/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-06/dars-2-test.html","student_link":"/9-sinf-iot/hafta-06/dars-2","tabs":[{"g":16,"link":"/mentor/9-sinf-iot/hafta-06/dars-1","current":false},{"g":17,"link":"/mentor/9-sinf-iot/hafta-06/dars-2","current":true},{"g":18,"link":"/mentor/9-sinf-iot/hafta-06/dars-3","current":false}],"prev":{"g":16,"title":"Mikrokontroller tushunchasi va IoT qurilmalaridagi o'rni (2-qism)","link":"/mentor/9-sinf-iot/hafta-06/dars-1"},"next":{"g":18,"title":"Arduino Uno va Tinkercad asosida svetofor tizimini modellashtirish (1-qism)","link":"/mentor/9-sinf-iot/hafta-06/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-06/dars-2.md","filePath":"mentor/9-sinf-iot/hafta-06/dars-2.md"}`),p={name:"mentor/9-sinf-iot/hafta-06/dars-2.md"},d={class:"blk"},u={id:"dars-rejasi",tabindex:"-1"},k={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},m={class:"blk"},y={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},c={id:"tezkor-nazorat-savollari",tabindex:"-1"},v={class:"blk"},b={id:"uyga-vazifa",tabindex:"-1"};function P(D,a,S,f,E,T){const s=r("Icon");return e(),h("div",null,[i("div",d,[i("h2",u,[n(s,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga ESP8266 va ESP32 ning IoT tizimlaridagi o&#39;rnini, asosiy farqlarini (tezlik, yadrolar, xotira, GPIO soni, Bluetooth), pin turlarini (GPIO, ADC, PWM, I2C, SPI), 3,3 V bilan ishlash qoidasini, sensor ma&#39;lumotini JSON ko&#39;rinishida HTTP/MQTT orqali bulutga yuborish tartibini, Arduino IDE va MicroPython tanlovini hamda energiya tejash g&#39;oyasini tushuntirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar eSP8266 va ESP32 ni 5 ta xususiyat bo&#39;yicha solishtiradi; 3,3 V qoidasini va 5 V ulashning xavfini tushuntiradi; gPIO, ADC, PWM, I2C, SPI pinlarining vazifasini ayta oladi; sensor ma&#39;lumotini JSON ko&#39;rinishida yozadi va protokolni (HTTP/MQTT) tanlaydi; arduino IDE va MicroPython farqini hamda Deep Sleep g&#39;oyasini biladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>14, 16-darslar: ESP, Wi-Fi, ADC, PWM: 10 daqiqa</li><li>ESP&#39;ning IoT dagi o&#39;rni va farqlar: 10 daqiqa</li><li>Pinlar va 3,3 V qoidasi: 20 daqiqa</li><li>Ma&#39;lumot yuborish: JSON, HTTP, MQTT: 15 daqiqa</li><li>Dasturlash tanlovi, Deep Sleep, xulosa: 25 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «ESP8266 va ESP32 mikrokontrollerlari haqida umumiy tushuncha»; o&#39;quv qo&#39;llanma — 2.3-bo&#39;lim (IoT&#39;dagi o&#39;rni, asosiy farqlar jadvali: tezlik, yadrolar, SRAM, GPIO ~17 va ~34+; GPIO, ADC, PWM, I2C, SPI; dual-core va Bluetooth; Arduino IDE va MicroPython; DHT11/BMP280/MQ sensorlari; aqlli chiroq va ob-havo stansiyasi; HTTP/MQTT va JSON), 2.2-bo&#39;lim (3,3 V xavfi, Wi-Fi termometr loyihasi). 14-darsdagi Wi-Fi kodi takrorlanmaydi. Deep Sleep namunasi ESP32 Arduino hujjatiga ko&#39;ra qo&#39;shildi; ESP kodlari plata yoki simulyatorda ishga tushirilmagan (MicroPython va JSON namunasining Python sintaksisi tekshirilgan).</p></blockquote><hr>",3))]),i("div",k,[i("h2",g,[n(s,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o(`<h3 id="_1-esp8266-va-esp32-o-rni-va-asosiy-farqlar" tabindex="-1">1. ESP8266 va ESP32: o&#39;rni va asosiy farqlar <a class="header-anchor" href="#_1-esp8266-va-esp32-o-rni-va-asosiy-farqlar" aria-label="Permalink to &quot;1. ESP8266 va ESP32: o&#39;rni va asosiy farqlar&quot;">​</a></h3><p>ESP8266 va ESP32 — IoT tizimlarining eng muhim qurilmalaridan: <strong>kichik, arzon, ichki Wi-Fi&#39;li</strong>; sensorlar va aktuatorlarni simsiz tarmoq orqali boshqaradi. Aqlli uyda harorat, namlik, yorug&#39;lik va harakat sensorlaridan ma&#39;lumot yig&#39;ib bulutga uzatadi, foydalanuvchi telefonidan nazorat qiladi; sanoatda masofaviy monitoring uchun ishlatiladi. <strong>ESP32 — ESP8266 ning halefi</strong>: ikki yadroli protsessor, katta xotira, tezkor Wi-Fi va Bluetooth. ESP8266 oddiy loyihalar uchun yetarli va arzon, lekin GPIO, RAM va tezligi cheklangan. Qo&#39;llanma jadvaliga ko&#39;ra: tezlik — 80 MHz (ESP8266) va 160–240 MHz (ESP32); yadro — 1 va 2; SRAM — cheklangan va katta; Bluetooth — yo&#39;q va bor; GPIO — taxminan 17 va 34+. Aniq raqamlar modelga qarab farq qiladi — plata hujjatini tekshiring. Tanlash qoidasi: oddiy sensor yoki rozetka → ESP8266; Bluetooth, ko&#39;p pin yoki murakkab hisob kerak → ESP32.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Xususiyat       ESP8266      ESP32</span></span>
<span class="line"><span>Tezlik          80 MHz       160-240 MHz</span></span>
<span class="line"><span>Yadro           1            2</span></span>
<span class="line"><span>SRAM            cheklangan   katta</span></span>
<span class="line"><span>Bluetooth       yo&#39;q         bor (Classic + BLE)</span></span>
<span class="line"><span>GPIO            ~17          ~34+</span></span>
<span class="line"><span>Kuchlanish      3.3 V        3.3 V</span></span></code></pre></div><blockquote><p>Professional maslahat: Jadvaldagi raqamlar taxminiy: «NodeMCU» va «DevKit» platalarida chiqarilgan pinlar soni boshqacha bo&#39;lishi mumkin.</p></blockquote><h3 id="_2-pinlar-gpio-adc-pwm-i2c-spi-va-3-3-v-qoidasi" tabindex="-1">2. Pinlar (GPIO, ADC, PWM, I2C, SPI) va 3,3 V qoidasi <a class="header-anchor" href="#_2-pinlar-gpio-adc-pwm-i2c-spi-va-3-3-v-qoidasi" aria-label="Permalink to &quot;2. Pinlar (GPIO, ADC, PWM, I2C, SPI) va 3,3 V qoidasi&quot;">​</a></h3><p>ESP platalari turli <strong>pinlar</strong> orqali sensorlar va aktuatorlarni boshqaradi (qo&#39;llanma): <strong>GPIO</strong> — raqamli signalni o&#39;qish va uzatish (LEDni yoqish); <strong>ADC</strong> — analog signalni raqamga aylantirish (yorug&#39;lik sensori); <strong>PWM</strong> — LED yorqinligi, motor tezligini silliq boshqarish; <strong>I2C</strong> va <strong>SPI</strong> — bir nechta qurilmani (displey, sensor) bir paytda ulash protokollari. <strong>Muhim qoida: ESP8266 ham, ESP32 ham 3,3 V da ishlaydi.</strong> Arduino Uno&#39;dagi kabi 5 V ulasangiz, chip ishdan chiqishi mumkin (qo&#39;llanma: «darhol ishdan chiqadi»). Sensor ham 3,3 V da ishlashi kerak: masalan, DHT11 ning VCC oyog&#39;i plataning 3,3 V iga, GND — GND ga, DATA — raqamli pinga ulanadi. 5 V li signalni 3,3 V pinga bevosita bermang — kuchlanish bo&#39;lgich yoki darajani o&#39;zgartiruvchi (level shifter) kerak. ESP32 da ikki yadro: biri sensorni o&#39;qiydi, ikkinchisi tarmoqni boshqaradi — bir vazifa ikkinchisini to&#39;xtatmaydi.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>DHT11            ESP (NodeMCU / DevKit)</span></span>
<span class="line"><span>VCC   -------&gt;   3.3V        (5V EMAS!)</span></span>
<span class="line"><span>GND   -------&gt;   GND</span></span>
<span class="line"><span>DATA  -------&gt;   raqamli pin (masalan, D4)</span></span></code></pre></div><blockquote><p>Professional maslahat: Plata va sensor modeliga qarab pin nomlari (D4, GPIO4) farq qiladi. Ulashdan oldin plata sxemasiga qarang.</p></blockquote><h3 id="_3-ma-lumotni-bulutga-yuborish-va-dasturlash-tanlovi" tabindex="-1">3. Ma&#39;lumotni bulutga yuborish va dasturlash tanlovi <a class="header-anchor" href="#_3-ma-lumotni-bulutga-yuborish-va-dasturlash-tanlovi" aria-label="Permalink to &quot;3. Ma&#39;lumotni bulutga yuborish va dasturlash tanlovi&quot;">​</a></h3><p>Sensor ma&#39;lumoti (DHT11, DHT22, BMP280, MQ gaz sensori) ESP orqali <strong>HTTP POST</strong> yoki <strong>MQTT</strong> bilan bulutga uzatiladi. Ma&#39;lumot <strong>JSON</strong> formatida tuziladi — tahlil va vizualizatsiya oson: <code>{&quot;temperature&quot;: 28.5, &quot;humidity&quot;: 60}</code>. Bulutda (ThingSpeak, Blynk kabi platformalar) ma&#39;lumot saqlanadi, grafik chiziladi, ogohlantirish (alert) va avtomatik boshqaruv yoqiladi. Loyihalar (qo&#39;llanma): <strong>aqlli chiroq</strong> (ESP + harakat sensori + rele + LED), <strong>ob-havo stansiyasi</strong> (ESP + DHT/BMP + bulut), <strong>masofadan boshqaruv</strong> (Wi-Fi + HTTP/MQTT + mobil ilova). <strong>Dasturlash:</strong> Arduino IDE — C/C++; MicroPython — Python sintaksisi; kod USB kabel orqali yuklanadi. <strong>Energiya tejash:</strong> batareyali qurilma ko&#39;p vaqt uxlab, faqat o&#39;lchash va yuborish uchun uyg&#39;onadi — ESP32 da bu <strong>Deep Sleep</strong> rejimi (taymer yoki tashqi signal bilan uyg&#39;onish).</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">from</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> machine </span><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">import</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> Pin</span></span>
<span class="line"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">import</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> time</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">led = Pin(</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">2</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">, Pin.OUT)   </span><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># ichki LED pini modelga bog&#39;liq</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">while</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> True</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">:</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">    led.value(</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">)</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">    time.sleep(</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0.5</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">)</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">    led.value(</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">)</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">    time.sleep(</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0.5</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">)</span></span></code></pre></div><blockquote><p>Professional maslahat: MicroPython&#39;da <code>Pin</code>, <code>time</code> kabi modullar ESP ichida ishlaydi. Pin raqami (masalan, 2) plata modeliga bog&#39;liq — hujjatga qarang.</p></blockquote><hr>`,13))]),i("div",m,[i("h2",y,[n(s,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-solishtirish-oson" tabindex="-1">1-topshiriq. Solishtirish (oson) <a class="header-anchor" href="#_1-topshiriq-solishtirish-oson" aria-label="Permalink to &quot;1-topshiriq. Solishtirish (oson)&quot;">​</a></h3><p>ESP8266 va ESP32 ni 4 ta xususiyat bo&#39;yicha solishtiring.</p><p><strong>Yechim:</strong> Tezlik — 80 MHz va 160–240 MHz; yadro — 1 va 2; Bluetooth — yo&#39;q va bor; GPIO — ~17 va ~34+.</p><h3 id="_2-topshiriq-kuchlanish-oson" tabindex="-1">2-topshiriq. Kuchlanish (oson) <a class="header-anchor" href="#_2-topshiriq-kuchlanish-oson" aria-label="Permalink to &quot;2-topshiriq. Kuchlanish (oson)&quot;">​</a></h3><p>ESP ga sensorni qaysi kuchlanishdan ulaysiz? 5 V ulansa nima bo&#39;ladi?</p><p><strong>Yechim:</strong> Sensor ham 3,3 V ga ulanadi. 5 V ulansa, ESP chipi ishdan chiqishi mumkin.</p><h3 id="_3-topshiriq-pin-turlari-o-rta" tabindex="-1">3-topshiriq. Pin turlari (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-pin-turlari-o-rta" aria-label="Permalink to &quot;3-topshiriq. Pin turlari (o&#39;rta)&quot;">​</a></h3><p>GPIO, ADC, PWM va I2C ning vazifasini bir gapdan yozing.</p><p><strong>Yechim:</strong> GPIO — raqamli kirish-chiqish; ADC — analogni raqamga aylantirish; PWM — yorqinlik/tezlikni silliq boshqarish; I2C — bir nechta qurilmani ulash protokoli.</p><h3 id="_4-topshiriq-json-yozish-o-rta" tabindex="-1">4-topshiriq. JSON yozish (o&#39;rta) <a class="header-anchor" href="#_4-topshiriq-json-yozish-o-rta" aria-label="Permalink to &quot;4-topshiriq. JSON yozish (o&#39;rta)&quot;">​</a></h3><p>Harorat 27,5 va namlik 55 qiymatlarini JSON ko&#39;rinishida yozing.</p><p><strong>Yechim:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">{</span><span style="--shiki-light:#0451A5;--shiki-dark:#9CDCFE;">&quot;temperature&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">: </span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">27.5</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">, </span><span style="--shiki-light:#0451A5;--shiki-dark:#9CDCFE;">&quot;humidity&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">: </span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">55</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">}</span></span></code></pre></div><h3 id="_5-topshiriq-loyiha-tanlash-qiyin" tabindex="-1">5-topshiriq. Loyiha tanlash (qiyin) <a class="header-anchor" href="#_5-topshiriq-loyiha-tanlash-qiyin" aria-label="Permalink to &quot;5-topshiriq. Loyiha tanlash (qiyin)&quot;">​</a></h3><p>Batareyada yillab ishlaydigan oddiy sensor va Bluetooth kerak bo&#39;lgan qurilma uchun qaysi chipni tanlaysiz? Nega?</p><p><strong>Yechim:</strong> Bluetooth kerak bo&#39;lsa — ESP32 (ESP8266 da Bluetooth yo&#39;q). Batareya uchun ko&#39;p vaqt uxlash (Deep Sleep) va faqat o&#39;lchash/yuborish paytida uyg&#39;onish kerak.</p><h3 id="_6-topshiriq-deep-sleep-g-oyasi-bonus" tabindex="-1">6-topshiriq. Deep Sleep g&#39;oyasi (bonus) <a class="header-anchor" href="#_6-topshiriq-deep-sleep-g-oyasi-bonus" aria-label="Permalink to &quot;6-topshiriq. Deep Sleep g&#39;oyasi (bonus)&quot;">​</a></h3><p>Ob-havo stansiyasi har 10 daqiqada o&#39;lchaydi. Energiyani qanday tejaysiz?</p><p><strong>Yechim:</strong> O&#39;lchash va yuborishdan keyin ESP32 ni Deep Sleep ga o&#39;tkazib, taymer bilan 10 daqiqadan keyin uyg&#39;otamiz; qolgan vaqt energiya deyarli sarflanmaydi.</p><hr>',20))]),i("div",q,[i("h2",c,[n(s,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>ESP32 ESP8266 dan nimasi bilan farq qiladi? <ul><li><em>Javob:</em> Ikki yadro, tezroq, ko&#39;p xotira va pin, Bluetooth bor.</li></ul></li><li>ESP qaysi kuchlanishda ishlaydi? <ul><li><em>Javob:</em> 3,3 V.</li></ul></li><li>GPIO nima? <ul><li><em>Javob:</em> Raqamli signalni o&#39;qish va uzatish uchun umumiy pin.</li></ul></li><li>Ma&#39;lumot qaysi formatda yuboriladi? <ul><li><em>Javob:</em> JSON, HTTP yoki MQTT orqali.</li></ul></li><li>Energiya tejash rejimi? <ul><li><em>Javob:</em> Deep Sleep.</li></ul></li></ol><hr>",2))]),i("div",v,[i("h2",b,[n(s,{name:"house"}),a[12]||(a[12]=l(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,"ESP8266 va ESP32 ni 6 ta xususiyat bo'yicha jadvalda solishtiring."),i("li",null,"DHT11 ni ESP ga ulash sxemasini daftaringizga chizing va nega 3,3 V ishlatilishini yozing."),i("li",null,"Harorat 24,0, namlik 48 va bosim 1012 qiymatlarini JSON ko'rinishida yozing."),i("li",null,"Aqlli chiroq yoki ob-havo stansiyasi loyihasining blok-sxemasini chizing: sensor, ESP, Wi-Fi, bulut, foydalanuvchi."),i("li",null,"Deep Sleep nima uchun kerakligini 3 jumlada tushuntiring.")],-1))])])}const C=t(p,[["render",P]]);export{z as __pageData,C as default};
